// ============================================================================
// 排球隊雲端管理系統 (app.js)
// 特色：
// 1. 柔和不刺眼「霧面黑白灰 × 排球」主題風格
// 2. 權限與資料規則：
//    - 體能與補體能：整合為同一專區（固定重訓與間歇格式：列為動作、欄為組數，含補體能連結與證明照片）
//    - 請假與全隊出席：請假單獨一個功能（含請假證明照片），並公開「全隊出席情況」（一般使用者與管理者皆可查看）
//    - 球隊經費收支：使用者與管理者皆可查看所有經費收支；僅管理者可新增/刪除
//    - 設定與帳號管理：公開登入頁無註冊；僅管理者可註冊新帳號及修改使用者姓名/帳號；使用者於設定僅能改密碼
// ============================================================================

const SUPABASE_PROJECT_URL = 'https://mtorunczoyjvhmufaast.supabase.co';
const SUPABASE_REST_URL = 'https://mtorunczoyjvhmufaast.supabase.co/rest/v1/';
