// 取得所有一般球員帳號 (排除管理者，管理者無須被指派體能或補體能)
function getPlayerUsers() {
  return state.users.filter(u => u.role !== 'admin');
}

// 暫存目前表單上傳壓縮後的 Base64 圖片
const photoBuffer = {
  'fit-rec-photo-input': '',
  'leave-photo-input': '',
  'edit-leave-photo-input': ''
};

// 取得今日 YYYY-MM-DD
function getTodayStr() {
  const d = new Date();
  const yyyy = d.getFullYear();
  const mm = String(d.getMonth() + 1).padStart(2, '0');
  const dd = String(d.getDate()).padStart(2, '0');
  return `${yyyy}-${mm}-${dd}`;
}

function generateUUID() {
  if (crypto && crypto.randomUUID) return crypto.randomUUID();
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    const r = Math.random() * 16 | 0;
    const v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
}

// 判斷一筆資料是否屬於目前登入的使用者
function isOwnedByCurrentUser(record) {
  if (!state.currentUser || !record) return false;
  return (
    record.user_id === state.currentUser.id ||
    record.user_name === state.currentUser.name
  );
}

