// --- 隊費與代繳費用操作 ---
function openFeeModal(mode = 'single') {
  document.getElementById('fee-mode').value = mode;
  document.getElementById('fee-due-date').value = getTodayStr();
  document.getElementById('fee-title').value = '';
  document.getElementById('fee-amount').value = '';
  document.getElementById('fee-note').value = '';
  document.getElementById('fee-is-paid').value = 'false';

  const selectWrap = document.getElementById('fee-member-select-wrap');
  const batchHint = document.getElementById('fee-batch-hint');
  const titleEl = document.getElementById('modal-fee-title');
  const userSelect = document.getElementById('fee-user-id');
  const isAdmin = state.currentUser.role === 'admin';

  const playerUsers = getPlayerUsers();
  if (mode === 'batch' && isAdmin) {
    titleEl.textContent = '全隊批發收費 (隊費 / 代繳費用)';
    selectWrap.classList.add('hidden');
    batchHint.classList.remove('hidden');
  } else {
    titleEl.textContent = '單筆新增隊費 / 代繳費用';
    selectWrap.classList.remove('hidden');
    batchHint.classList.add('hidden');
    if (isAdmin) {
      userSelect.innerHTML = playerUsers.map(u => `<option value="${u.id}">${escapeHtml(u.name)} (${escapeHtml(u.jersey_number || u.username)})</option>`).join('');
      if (playerUsers.length > 0) userSelect.value = playerUsers[0].id;
    } else {
      userSelect.innerHTML = `<option value="${state.currentUser.id}">${escapeHtml(state.currentUser.name)}</option>`;
      userSelect.value = state.currentUser.id;
    }
  }

  document.getElementById('modal-fee').classList.remove('hidden');
}

function setQuickFee(type, title, amount) {
  document.getElementById('fee-type').value = type;
  document.getElementById('fee-title').value = title;
  document.getElementById('fee-amount').value = amount;
}

async function submitFeeForm(e) {
  e.preventDefault();
  const mode = document.getElementById('fee-mode').value;
  const feeType = document.getElementById('fee-type').value;
  const title = document.getElementById('fee-title').value.trim();
  const amount = parseInt(document.getElementById('fee-amount').value, 10) || 0;
  const dueDate = document.getElementById('fee-due-date').value;
  const isPaid = document.getElementById('fee-is-paid').value === 'true';
  const note = document.getElementById('fee-note').value.trim();

  let records = [];
  if (mode === 'batch' && state.currentUser.role === 'admin') {
    records = getPlayerUsers().map(u => ({
      id: generateUUID(),
      user_id: u.id,
      user_name: u.name,
      fee_type: feeType,
      title,
      amount,
      due_date: dueDate,
      is_paid: isPaid,
      payment_note: note,
      updated_at: new Date().toISOString()
    }));
  } else {
    const uid = document.getElementById('fee-user-id').value;
    const targetUser = (state.currentUser.role === 'admin' && state.users.find(u => u.id === uid)) || state.currentUser;
    records = [{
      id: generateUUID(),
      user_id: targetUser.id,
      user_name: targetUser.name,
      fee_type: feeType,
      title,
      amount,
      due_date: dueDate,
      is_paid: isPaid,
      payment_note: note,
      updated_at: new Date().toISOString()
    }];
  }

  closeModal('modal-fee');

  if (state.isSupabaseReady) {
    const { error } = await supabaseClient.from('team_fees').insert(records);
    if (error) {
      showToast('新增失敗：' + error.message, 'error');
      return;
    }
    await fetchAllFromSupabase(false);
  } else {
    state.fees.unshift(...records);
    renderAll();
  }
  await notifyRealtimePeers();
  showToast(mode === 'batch' ? `已對全隊 ${records.length} 人建立「${title}」收費紀錄！` : '已新增費用紀錄！', 'success');
}

