async function submitLeaveForm(e) {
  e.preventDefault();
  const uid = document.getElementById('leave-user-id').value;
  const targetUser = (state.currentUser.role === 'admin' && state.users.find(u => u.id === uid)) || state.currentUser;
  const leaveDate = document.getElementById('leave-date').value;
  const leaveType = document.getElementById('leave-type').value;
  const sessionName = document.getElementById('leave-session').value.trim();
  const reason = document.getElementById('leave-reason').value.trim();
  const leavePhoto = photoBuffer['leave-photo-input'] || '';

  const newLeave = {
    id: generateUUID(),
    user_id: targetUser.id,
    user_name: targetUser.name,
    leave_date: leaveDate,
    leave_type: leaveType,
    session_name: sessionName,
    reason,
    leave_photo: leavePhoto,
    makeup_text: '',
    makeup_photo: '',
    makeup_done: false,
    status: '已核准', // 假單免批准直接生效
    created_at: new Date().toISOString()
  };

  closeModal('modal-leave');
  state.selectedAttendanceDate = leaveDate;

  if (state.isSupabaseReady) {
    const { error } = await supabaseClient.from('team_leaves').insert([newLeave]);
    if (error) {
      const fallbackLeave = {
        id: newLeave.id,
        user_id: newLeave.user_id,
        user_name: newLeave.user_name,
        leave_date: newLeave.leave_date,
        leave_type: newLeave.leave_type,
        session_name: newLeave.session_name,
        reason: newLeave.reason,
        status: newLeave.status,
        created_at: newLeave.created_at
      };
      await supabaseClient.from('team_leaves').insert([fallbackLeave]);
      state.leaves.unshift(newLeave);
      renderAll();
      showToast('已登記請假單並更新全隊出席看板！', 'info');
      await notifyRealtimePeers();
      return;
    }
    await fetchAllFromSupabase(false);
  } else {
    state.leaves.unshift(newLeave);
    renderAll();
  }
  await notifyRealtimePeers();
  showToast('已登記請假單，並同步更新至全隊出席情況看板！', 'success');
}

