function exportFinancesCSV() {
  if (state.finances.length === 0) {
    showToast('目前無經費資料可匯出', 'info');
    return;
  }
  const headers = ['日期', '類型', '科目分類', '項目摘要', '金額', '經手人', '備註'];
  const rows = state.finances.map(tx => [
    tx.tx_date,
    tx.tx_type,
    tx.category,
    `"${(tx.title || '').replace(/"/g, '""')}"`,
    tx.tx_type === '支出' ? -Math.abs(tx.amount) : Math.abs(tx.amount),
    `"${(tx.handler || '').replace(/"/g, '""')}"`,
    `"${(tx.note || '').replace(/"/g, '""')}"`
  ]);
  const csvContent = '\uFEFF' + [headers.join(','), ...rows.map(r => r.join(','))].join('\n');
  const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = `排球隊經費收支報表_${getTodayStr()}.csv`;
  link.click();
  URL.revokeObjectURL(url);
  showToast('已匯出 CSV 經費報表！', 'success');
}

// ============================================================================
// 設定分頁操作：
// 1. 使用者與管理者修改個人密碼 (submitChangeMyPassword)
// 2. 僅管理者可註冊新帳號與修改任何使用者的姓名/登入帳號 (openMemberModal / openEditMemberModal / submitMemberForm)
// ============================================================================

async function submitChangeMyPassword(e) {
  e.preventDefault();
  if (!state.currentUser) return;

  const oldPwd = document.getElementById('pwd-old').value.trim();
  const newPwd = document.getElementById('pwd-new').value.trim();
  const confirmPwd = document.getElementById('pwd-confirm').value.trim();

  if (oldPwd !== state.currentUser.password) {
    showToast('目前舊密碼輸入錯誤！', 'error');
    return;
  }
  if (!newPwd) {
    showToast('新密碼不能為空！', 'error');
    return;
  }
  if (newPwd !== confirmPwd) {
    showToast('兩次輸入的新密碼不一致！', 'error');
    return;
  }

  state.currentUser.password = newPwd;
  const userInList = state.users.find(u => u.id === state.currentUser.id);
  if (userInList) userInList.password = newPwd;
  sessionStorage.setItem(SESSION_USER_KEY, JSON.stringify(state.currentUser));

  document.getElementById('pwd-old').value = '';
  document.getElementById('pwd-new').value = '';
  document.getElementById('pwd-confirm').value = '';

  if (state.isSupabaseReady) {
    const { error } = await supabaseClient
      .from('team_users')
      .update({ password: newPwd })
      .eq('id', state.currentUser.id);
    if (error) {
      showToast('雲端更新密碼失敗：' + error.message, 'error');
      return;
    }
  }

  await notifyRealtimePeers();
  showToast('您的登入密碼已成功更新！', 'success');
}

