async function submitMemberForm(e) {
  e.preventDefault();
  if (!state.currentUser || state.currentUser.role !== 'admin') return;

  const editId = document.getElementById('member-edit-id').value.trim();
  const username = document.getElementById('member-username').value.trim();
  const password = document.getElementById('member-password').value.trim();
  const name = document.getElementById('member-name').value.trim();
  const jersey = document.getElementById('member-jersey').value.trim() || '#00 排球隊員';
  const role = document.getElementById('member-role').value;

  // 檢查帳號是否與其他人重複
  const duplicate = state.users.find(
    u => u.username.toLowerCase() === username.toLowerCase() && u.id !== editId
  );
  if (duplicate) {
    showToast('此登入帳號名稱已被其他成員使用！', 'error');
    return;
  }

  closeModal('modal-member');

  if (editId) {
    // 編輯既有成員 (管理者修改姓名、帳號、密碼、位置或角色)
    const target = state.users.find(u => u.id === editId);
    if (!target) return;
    const oldName = target.name;

    target.username = username;
    target.password = password;
    target.name = name;
    target.jersey_number = jersey;
    target.role = role;

    // 同步更新關聯紀錄上的顯示姓名
    state.fitness.forEach(f => { if (f.user_id === editId || f.user_name === oldName) f.user_name = name; });
    state.fees.forEach(f => { if (f.user_id === editId || f.user_name === oldName) f.user_name = name; });
    state.leaves.forEach(l => { if (l.user_id === editId || l.user_name === oldName) l.user_name = name; });

    if (state.currentUser.id === editId) {
      state.currentUser = { ...target };
      sessionStorage.setItem(SESSION_USER_KEY, JSON.stringify(state.currentUser));
    }

    if (state.isSupabaseReady) {
      const { error } = await supabaseClient
        .from('team_users')
        .update({ username, password, name, jersey_number: jersey, role })
        .eq('id', editId);
      if (error) {
        showToast('更新失敗：' + error.message, 'error');
        return;
      }
      if (oldName !== name) {
        await Promise.all([
          supabaseClient.from('team_fitness').update({ user_name: name }).eq('user_id', editId),
          supabaseClient.from('team_fees').update({ user_name: name }).eq('user_id', editId),
          supabaseClient.from('team_leaves').update({ user_name: name }).eq('user_id', editId)
        ]);
      }
      await fetchAllFromSupabase(false);
    } else {
      renderNavigation();
      renderAll();
    }
    await notifyRealtimePeers();
    showToast(`已成功修改成員「${name} (@${username})」的帳號資料！`, 'success');
  } else {
    // 管理者註冊新成員帳號
    const newUser = {
      id: generateUUID(),
      username,
      password,
      name,
      jersey_number: jersey,
      role,
      created_at: new Date().toISOString()
    };

    if (state.isSupabaseReady) {
      const { error } = await supabaseClient.from('team_users').insert([newUser]);
      if (error) {
        showToast('註冊失敗：' + error.message, 'error');
        return;
      }
      await fetchAllFromSupabase(false);
    } else {
      state.users.push(newUser);
      renderAll();
    }
    await notifyRealtimePeers();
    showToast(`已成功註冊新成員：${name} (@${username})`, 'success');
  }
}

async function deleteMemberAccount(id) {
  if (!state.currentUser || state.currentUser.role !== 'admin') return;
  const user = state.users.find(u => u.id === id);
  if (!user) return;
  if (!window.confirm(`確定要刪除成員「${user.name}」的帳號嗎？`)) return;

  state.users = state.users.filter(u => u.id !== id);
  renderAll();

  if (state.isSupabaseReady) {
    await supabaseClient.from('team_users').delete().eq('id', id);
  }
  await notifyRealtimePeers();
  showToast(`已移除成員 ${user.name}`, 'info');
}

// ============================================================================
// Supabase SQL 建表輔助視窗與工具函式
// ============================================================================

function openSqlSetupModal() {
  const textarea = document.getElementById('sql-script-textarea');
  if (textarea) textarea.value = SQL_SETUP_SCRIPT;
  document.getElementById('modal-sql-setup').classList.remove('hidden');
}

async function copySqlScript() {
  try {
    await navigator.clipboard.writeText(SQL_SETUP_SCRIPT);
    showToast('已複製 SQL 建表語法！請貼上至 Supabase SQL Editor 並點擊 Run', 'success');
  } catch (e) {
    const textarea = document.getElementById('sql-script-textarea');
    if (textarea) {
      textarea.select();
      document.execCommand('copy');
      showToast('已複製 SQL 建表語法！', 'success');
    }
  }
}

async function recheckAndSyncSupabase() {
  showToast('正在檢測 Supabase 資料表並同步資料...', 'info');
  const ok = await fetchAllFromSupabase(true);
  if (ok) {
    showToast('Supabase 資料表連線成功！所有資料已即時同步至雲端', 'success');
    closeModal('modal-sql-setup');
  } else {
    showToast('尚未偵測到資料表，請確認已在 Supabase SQL Editor 執行語法 (點擊 Run)', 'error');
  }
}

function closeModal(modalId) {
  const el = document.getElementById(modalId);
  if (el) el.classList.add('hidden');
}

function setQuickValue(inputId, val) {
  const el = document.getElementById(inputId);
  if (el) el.value = val;
}

function escapeHtml(str) {
  if (str === null || str === undefined) return '';
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

function escapeJsStr(str) {
  if (str === null || str === undefined) return '';
  return String(str).replace(/\\/g, '\\\\').replace(/'/g, "\\'");
}

function showToast(message, type = 'info') {
  const container = document.getElementById('toast-container');
  if (!container) return;

  const colors = {
    success: 'bg-[#1c1b18] text-stone-100 border-stone-700',
    error: 'bg-stone-800 text-stone-100 border-stone-600',
    info: 'bg-stone-900 text-stone-200 border-stone-700'
  };

  const toast = document.createElement('div');
  toast.className = `pointer-events-auto px-4 py-3 rounded-xl shadow-xl border text-xs sm:text-sm font-bold flex items-center justify-between gap-2 transition-all duration-300 ${colors[type] || colors.info}`;
  toast.innerHTML = `<span>🏐 ${escapeHtml(message)}</span>`;
  container.appendChild(toast);

  setTimeout(() => {
    toast.style.opacity = '0';
    toast.style.transform = 'translateY(-8px)';
    setTimeout(() => toast.remove(), 300);
  }, 3200);
}

// ============================================================================
// 系統啟動初始化
// ============================================================================

window.addEventListener('DOMContentLoaded', async () => {
  loadLocalCache();
  lucide.createIcons();

  try {
    const savedSession = sessionStorage.getItem(SESSION_USER_KEY);
    if (savedSession) {
      const parsedUser = JSON.parse(savedSession);
      if (parsedUser && parsedUser.username) {
        state.currentUser = parsedUser;
        document.getElementById('auth-screen').classList.add('hidden');
        document.getElementById('app-screen').classList.remove('hidden');
        renderNavigation();
        renderAll();
      }
    }
  } catch (e) {
    console.warn('Session restore warning:', e);
  }

  await fetchAllFromSupabase(false);
  setupRealtimeSubscriptions();
});
